//! PlayUnownedService — manages play_unowned_games.lua which lets Steam
//! launch games not owned by the account via SLSsteam hooks.

use std::fs;
use std::path::PathBuf;

use crate::services::slssteam_service::SlssteamService;

const PLUGIN_FILENAME: &str = "play_unowned_games.lua";
const PLUGIN_SOURCE: &str = r#"-- PlayUnownedGames — allows playing not-owned games via SLSsteam spoofing
-- Auto-generated by LuaTools Linux v2.2.0-beta

addappid(%APP_ID%, 1, "placeholder")

-- Force Steam to treat this app as owned by spoofing license response
-- SLSsteam intercepts ISteamUser::BIsSubscribedApp and returns true for listed appids

-- Enable free-on-demand access
local steam_user = steam_api.ISteamUser()
if steam_user then
    steam_user.BIsSubscribedApp = function(appid)
        if appid == %APP_ID% then
            return true
        end
        return steam_user:Original_BIsSubscribedApp(appid)
    end
end

-- Block license check dialogs
local steam_apps = steam_api.ISteamApps()
if steam_apps then
    steam_apps.BIsSubscribedApp = function(appid)
        if appid == %APP_ID% then
            return true
        end
        return steam_apps:Original_BIsSubscribedApp(appid)
    end
end

-- Always return owned for this appid
print("[PlayUnownedGames] Enabled for AppID %APP_ID%")
"#;

pub struct PlayUnownedService {
    steam_installation: std::sync::Arc<crate::models::steam::SteamInstallation>,
    slssteam_service: std::sync::Arc<std::sync::Mutex<SlssteamService>>,
}

impl PlayUnownedService {
    pub fn new(
        steam_installation: crate::models::steam::SteamInstallation,
        slssteam_service: SlssteamService,
    ) -> Self {
        Self {
            steam_installation: std::sync::Arc::new(steam_installation),
            slssteam_service: std::sync::Arc::new(std::sync::Mutex::new(slssteam_service)),
        }
    }

    pub fn stplug_in_dir(&self) -> PathBuf {
        self.steam_installation.stplug_in_path.clone()
    }

    pub fn lua_path(&self) -> PathBuf {
        self.stplug_in_dir().join(PLUGIN_FILENAME)
    }

    pub fn is_installed(&self) -> bool {
        self.lua_path().exists()
    }

    pub fn is_enabled(&self) -> bool {
        let sls = self.slssteam_service.lock().unwrap();
        sls.config.play_not_owned
    }

    pub fn set_enabled(&mut self, enabled: bool) -> bool {
        let mut sls = self.slssteam_service.lock().unwrap();
        sls.config.play_not_owned = enabled;
        if enabled {
            if !self.lua_path().exists() {
                if let Err(_e) = self.install_plugin() {
                    sls.config.play_not_owned = false;
                    return false;
                }
            }
        }
        sls.save()
    }

    pub fn install_plugin(&self) -> std::io::Result<()> {
        let stplug = self.stplug_in_dir();
        fs::create_dir_all(&stplug)?;
        let content = PLUGIN_SOURCE.replace("%APP_ID%", "0");
        fs::write(self.lua_path(), &content)?;
        Ok(())
    }

    pub fn enable_for_app(&mut self, app_id: u32) -> bool {
        let mut sls = self.slssteam_service.lock().unwrap();

        let content = PLUGIN_SOURCE.replace("%APP_ID%", &app_id.to_string());
        if let Err(_) = fs::write(self.lua_path(), &content) {
            return false;
        }

        sls.add_additional_app(app_id);

        if sls.get_fake_app_id(app_id).is_none() {
            sls.set_fake_app_id(app_id, 480);
        }

        sls.config.play_not_owned = true;

        sls.save()
    }

    pub fn disable_for_app(&mut self, app_id: u32) -> bool {
        let mut sls = self.slssteam_service.lock().unwrap();

        sls.remove_additional_app(app_id);
        sls.remove_fake_app_id(app_id);

        let remaining = sls.config.additional_apps.len();
        if remaining == 0 {
            sls.config.play_not_owned = false;
            let _ = fs::remove_file(self.lua_path());
        }

        sls.save()
    }

    pub fn get_managed_app_ids(&self) -> Vec<u32> {
        let sls = self.slssteam_service.lock().unwrap();
        sls.config.additional_apps.clone()
    }
}

impl std::fmt::Debug for PlayUnownedService {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("PlayUnownedService")
            .field("stplug_in_dir", &self.stplug_in_dir())
            .field("is_installed", &self.is_installed())
            .field("is_enabled", &self.is_enabled())
            .finish()
    }
}